BEGIN;
SET LOCAL lock_timeout = '15s';

CREATE TABLE public.app_game_team_possessions (
    "competition_code" TEXT NOT NULL,
    "season_code" TEXT NOT NULL,
    "game_code" INTEGER NOT NULL,
    "side" TEXT NOT NULL,
    "club_code" TEXT,
    "opponent_club_code" TEXT,
    "counted_possessions" INTEGER,
    "possession_seconds" NUMERIC,
    "avg_possession_seconds" NUMERIC,
    "estimated_possessions" NUMERIC,
    PRIMARY KEY (competition_code, season_code, game_code, side)
);

CREATE TABLE public.app_game_team_score_flow (
    "competition_code" TEXT NOT NULL,
    "season_code" TEXT NOT NULL,
    "game_code" INTEGER NOT NULL,
    "side" TEXT NOT NULL,
    "club_code" TEXT,
    "opponent_club_code" TEXT,
    "points_for" INTEGER,
    "points_against" INTEGER,
    "lead_changes" INTEGER,
    "ties" INTEGER,
    "time_leading_seconds" NUMERIC,
    "time_trailing_seconds" NUMERIC,
    "time_tied_seconds" NUMERIC,
    "largest_lead" INTEGER,
    "longest_run" INTEGER,
    "runs_6_plus" INTEGER,
    "clutch_seconds" NUMERIC,
    "clutch_points_for" INTEGER,
    "clutch_points_against" INTEGER,
    PRIMARY KEY (competition_code, season_code, game_code, side)
);

CREATE TABLE public.app_game_team_shot_splits (
    "competition_code" TEXT NOT NULL,
    "season_code" TEXT NOT NULL,
    "game_code" INTEGER NOT NULL,
